using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

// Existing consumers: increment only, not a new UI first or native rule test.
public static class DiceCombinationPresentationValidation
{
 public static bool Running{get;private set;}
 public static string Output{get;private set;}
 static readonly System.Reflection.BindingFlags Flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
 [Serializable] class Result {public string folder,status;}
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static ForgeSeatView Read(string scenario,string label){string root=".tools/dice-combinations-1007/native/"+scenario;var paths=Directory.GetFiles(root,"result.json",SearchOption.AllDirectories).Where(p=>JsonUtility.FromJson<Result>(File.ReadAllText(p)).status=="PASS").ToArray();Check(paths.Length==1,"Ambiguous native producer");string p=JsonUtility.FromJson<Result>(File.ReadAllText(paths[0])).folder+"/"+label+"-seat1.json";string name=scenario+"-"+label; if(!File.Exists(Output+"/inputs/"+name+".json")){File.Copy(p,Output+"/inputs/"+name+".json");File.AppendAllText(Output+"/inputs.tsv",name+"\t"+p+"\n");}return JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));}
 static IEnumerator Frame(){yield return new WaitForEndOfFrame();yield return null;Canvas.ForceUpdateCanvases();}
 static void Click(Button b){Canvas.ForceUpdateCanvases();var e=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,b.transform.TransformPoint(((RectTransform)b.transform).rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);Check(b.interactable&&hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==b,"Dice ray blocked "+b.name);ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,e,ExecuteEvents.pointerClickHandler);}
 public static void Run(){Check(Application.isPlaying&&!Running,"Play required/already running");var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("DiceCombinationValidation").AddComponent<ForgeBattlefieldController>();Running=true;Output=".tools/dice-combinations-1007/ui/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output+"/inputs");Directory.CreateDirectory(Output+"/sources");File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(".tools/dice-combinations-1007/ui/latest.txt",Output);foreach(string p in new[]{"Assets/Scripts/Editor/DiceCombinationPresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.Notices.cs","Assets/Scripts/UI/ForgeBattlefieldController.GenericChoices.cs","Assets/Scripts/UI/ForgeBattlefieldController.CardSelection.cs"})File.Copy(p,Output+"/sources/"+Path.GetFileName(p));ui.StartCoroutine(Guard(ui));}
 static IEnumerator Guard(ForgeBattlefieldController ui){var tasks=new Stack<IEnumerator>();tasks.Push(Validate(ui));try{while(tasks.Count>0){object next;try{var t=tasks.Peek();if(!t.MoveNext()){tasks.Pop();continue;}next=t.Current;}catch(Exception e){File.WriteAllText(Output+"/result.txt","FAIL "+e);throw;}if(next is IEnumerator nested)tasks.Push(nested);else yield return next;}File.WriteAllText(Output+"/result.txt","PASS: remaining UI differences: zh-CN source/reroll/reset/legacy; en-US/ja-JP numeric/binary/source/reroll/reset/legacy. Six earlier zh-CN numeric/binary PASS steps remain in original failed source-control harness run, separately audited; actual native low/high/duplicate result IDs, two-source picker and confirmation, two selected dice plus reset/confirm, real rays/stale/duplicate/viewer guards, fixed font and bounded localized dice/counter prompts; legacy coin/inc/dec consumers sampled. UI increment only; native costs/rolls/outcomes independently tested, no live network/all-text claim.");}finally{while(tasks.Count>0)(tasks.Pop() as IDisposable)?.Dispose();Running=false;}}
 static IEnumerator Validate(ForgeBattlefieldController ui)
 {
  string locale=GamePreferences.Language;bool enabled=ui.enabled;ui.enabled=false;var migration=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldMigrationNotice>();bool migrationEnabled=migration!=null&&migration.enabled;if(migration!=null)migration.enabled=false;var module=EventSystem.current.currentInputModule;bool moduleEnabled=module!=null&&module.enabled;if(module!=null)module.enabled=false;
  try{foreach(string language in new[]{"zh-CN","en-US","ja-JP"}){
   int revision=GamePreferences.Revision;bool changing=GamePreferences.Language!=language;GamePreferences.SetLanguage(language);float until=Time.realtimeSinceStartup+12;while((!GamePreferences.Ready||changing&&GamePreferences.Revision==revision)&&Time.realtimeSinceStartup<until)yield return null;Check(GamePreferences.Ready,"Locale not ready");
   var samples=new[]{("choose-low","chosen-result",0),("choose-high","chosen-result",1),("reroll-both","chosen-result",1),("multiple-modifiers","modifier-cost-0",0),("multiple-modifiers","increment-1",0),("multiple-modifiers","increment-2",1)};
   foreach(var sample in language=="zh-CN"?Array.Empty<(string,string,int)>():samples){var v=Read(sample.Item1,sample.Item2);int calls=0,last=-1;Action<int> submit=i=>{calls++;last=i;};ui.Present(null,1,false,null,null,"");ui.Present(v,1,true,submit,null,"");yield return Frame();var menu=GameObject.Find("CardAbilityChoices");Check(menu!=null,"Dice menu absent");var title=menu.GetComponentsInChildren<Text>().Single(t=>t.name=="ValueTitle");Check(!title.resizeTextForBestFit,"Title autofit");
    if(sample.Item2=="chosen-result")Check(title.text==(language=="zh-CN"?"选择一个骰子结果":language=="ja-JP"?"サイコロの出目を選択":"Choose a die result"),"Dice result mislabeled/untranslated");
    if(sample.Item2.StartsWith("increment"))Check(title.text.StartsWith(language=="zh-CN"?"将骰值":language=="ja-JP"?"出目":"Increase or decrease"),"Binary dice prompt untranslated");
    if(sample.Item2.StartsWith("modifier-cost"))Check(title.text.StartsWith(language=="zh-CN"?"从 ":language=="ja-JP"?"ゼノリス": "Remove ")||language=="ja-JP"&&title.text.Contains("取り除きますか"),"Counter cost untranslated");
    var settings=title.GetGenerationSettings(title.rectTransform.rect.size);Check(title.cachedTextGeneratorForLayout.GetPreferredHeight(title.text,settings)<=title.rectTransform.rect.height+2,"Dice title clipped");
    var fonts=menu.GetComponentsInChildren<Text>().Select(t=>t.fontSize).ToArray();ui.Choose(sample.Item3,v.request.requestId-1);Check(calls==0,"Stale dice choice accepted");var b=menu.GetComponentsInChildren<Button>().Single(x=>x.name=="ValueOption_"+sample.Item3);Click(b);ui.Choose(sample.Item3,v.request.requestId);Check(calls==1&&last==sample.Item3,"Native dice index/duplicate mismatch");
    ui.Present(v,1,false,submit,null,"");yield return Frame();ui.Choose(sample.Item3,v.request.requestId);Check(calls==1,"Viewer submitted dice choice");Check(fonts.SequenceEqual(menu.GetComponentsInChildren<Text>().Select(t=>t.fontSize)),"Dice fonts changed");File.AppendAllText(Output+"/steps.log",language+" "+sample.Item1+" "+sample.Item2+" PASS\n");
   }
   // Native two-card modifier choice; no manufactured option IDs.
   foreach(string label in new[]{"request-28","request-30"}){var v=Read("multiple-modifiers",label);int calls=0,last=-1;ui.Present(null,1,false,null,null,"");ui.Present(v,1,true,i=>{calls++;last=i;},null,"");yield return Frame();int index=Array.FindIndex(v.request.options,o=>o.id==(label=="request-28"?"card:138":"ok"));Check(index>=0,"Native source/confirm missing");var control=UnityEngine.Object.FindObjectsByType<Button>(FindObjectsSortMode.None).FirstOrDefault(b=>b.gameObject.activeInHierarchy&&(label=="request-28"?b.name=="Artwork"&&b.transform.parent.name=="ChoiceCard_"+v.request.options[index].card.id:b.name=="SelectionAction_"+index));Check(control!=null,"Source control absent");Click(control);Check(calls==1&&last==index,"Source native identity mismatch");File.AppendAllText(Output+"/steps.log",language+" modifier "+label+" PASS\n");}
   ui.Present(null,1,false,null,null,"");
   foreach(int count in new[]{0,1,2}){var v=Read("reroll-both","reroll-selected-"+count);int calls=0,last=-1;ui.Present(v,1,true,i=>{calls++;last=i;},null,"");yield return Frame();var menu=GameObject.Find("CardAbilityChoices");Check(menu!=null,"Reroll menu absent");var progress=menu.GetComponentsInChildren<Text>().Single(t=>t.name=="GenericProgress");Check(progress.text.Contains(count.ToString())&&progress.text.Contains("0–2"),"Native multiselect counts lost");int index=Array.FindIndex(v.request.options,o=>o.id==(count==2?"confirm-cards":"select:"+count));var b=menu.GetComponentsInChildren<Button>().Single(x=>x.name==(count==2?"GenericConfirm":"GenericOption_"+index));Click(b);Check(calls==1&&last==index,"Multiselect native index wrong");ui.Choose(index,v.request.requestId);Check(calls==1,"Duplicate multiselect submitted");File.AppendAllText(Output+"/steps.log",language+" reroll selected"+count+" PASS\n");}
   var reset=Read("reroll-both","reroll-selected-1");int resetCalls=0,resetIndex=-1;ui.Present(null,1,false,null,null,"");ui.Present(reset,1,true,i=>{resetCalls++;resetIndex=i;},null,"");yield return Frame();Click(GameObject.Find("GenericReset").GetComponent<Button>());Check(resetCalls==1&&resetIndex==Array.FindIndex(reset.request.options,o=>o.id=="reset-cards"),"Reroll reset mismatch");
   foreach(string legacy in new[]{"xeno-dec-increment-choice","thumb-win-thumb-choice"}){string path="Tools/Validation/Reports/RandomMechanics/"+legacy+".json";if(!File.Exists(Output+"/inputs/"+legacy+".json"))File.Copy(path,Output+"/inputs/"+legacy+".json");var v=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(path));int calls=0,last=-1;ui.Present(null,1,false,null,null,"");ui.Present(v,1,true,i=>{calls++;last=i;},null,"");yield return Frame();int index=legacy.StartsWith("xeno")?1:0;Click(GameObject.Find("ValueOption_"+index).GetComponent<Button>());Check(calls==1&&last==index,"Legacy dice/coin index changed");File.AppendAllText(Output+"/steps.log",language+" legacy "+legacy+" PASS\n");}
   ui.Present(null,1,false,null,null,"");ui.Present(Read("reroll-both","reroll-selected-2"),1,true,_=>{},null,"");yield return Frame();yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Output+"/"+language+"-two-dice.png");yield return new WaitForSecondsRealtime(.2f);
  }}finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;if(migration!=null)migration.enabled=migrationEnabled;if(module!=null)module.enabled=moduleEnabled;GamePreferences.SetLanguage(locale);}
 }
}
#endif
